<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;font-size:12px}h1{font-size:22px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #999;padding:8px;text-align:left}</style></head><body><h1>INVOICE</h1><p><strong>{{ setting('company_name','Studio Freelance') }}</strong><br>{{ setting('company_address','') }}</p><p>Nomor: {{ $invoice->number }}<br>Tanggal: {{ $invoice->issued_at->format('d/m/Y') }}<br>Jatuh tempo: {{ $invoice->due_date->format('d/m/Y') }}</p><p>Kepada: {{ $invoice->order?->client?->name ?: '-' }}</p><table><tr><th>Deskripsi</th><th>Jumlah</th></tr><tr><td>{{ $invoice->order?->title ?: 'Layanan' }}</td><td>{{ format_rupiah($invoice->subtotal) }}</td></tr><tr><td>Pajak</td><td>{{ format_rupiah($invoice->tax_amount) }}</td></tr><tr><th>Total</th><th>{{ format_rupiah($invoice->total) }}</th></tr></table><p>Rekening: {{ setting('bank_name','') }} {{ setting('bank_account_number','') }} a.n. {{ setting('bank_account_name','') }}</p></body></html>
